    {
      "when": "not urgent and not do_not_disturb",
      "then": "False",
      "source": "P2"
    },
    {
      "when": "not urgent and do_not_disturb",
      "then": "False",
      "source": "P3"
    },
    {
      "when": "urgent and not do_not_disturb",
      "then": "True",
      "source": "P2"
    },
    {
      "when": "urgent and do_not_disturb",
      "then": "True",
      "source": "P2"
    },
    {
      "when": "do_not_disturb",
      "then": "False",
      "source": "P3"
    },
    {
      "when": "not urgent",
      "then": "False",
      "source": "P2"
    },
    {
      "when": "not do_not_disturb",
      "then": "False",
      "source": "P3"
    }
  ]
}
